function lsGet(k){try{return localStorage.getItem(k)}catch(e){return null}}
function lsSet(k,v){try{localStorage.setItem(k,v)}catch(e){}}
let LANG = lsGet('planit-lang') || 'ko';

function applyLang(){
  document.querySelectorAll('[data-i]').forEach(el=>{
    const en=EN[el.dataset.i];
    if(en===undefined) return;                                  /* 사전에 없는 키(내부 인덱스 등)는 건드리지 않음 */
    if(el.dataset.ko===undefined) el.dataset.ko=el.innerHTML;   /* 한국어 원본 보존 */
    const target = (LANG==='en') ? en : el.dataset.ko;
    if(el.innerHTML!==target) el.innerHTML=target;              /* 불필요한 재작성(리스너 파괴) 방지 */
  });
  document.querySelectorAll('.langbtn span').forEach(s=>s.classList.toggle('on', s.dataset.l===LANG));
  document.documentElement.lang = LANG==='ko'?'ko':'en';
  window.dispatchEvent(new CustomEvent('langchange'));
}
document.addEventListener('click',e=>{
  const s=e.target.closest('.langbtn span'); if(!s) return;
  LANG=s.dataset.l; lsSet('planit-lang',LANG); applyLang();
});
applyLang();
document.addEventListener('keydown',e=>{
  if(e.key!=='Enter'&&e.key!==' ') return;
  const s=e.target.closest&&e.target.closest('.langbtn span'); if(!s) return;
  e.preventDefault(); LANG=s.dataset.l; lsSet('planit-lang',LANG); applyLang();
});

