"IMO 2023 온실가스 감축전략 · 국제해운 넷제로를 2050년 무렵으로 잡고, 2030·2040년 중간 점검치를 둔 IMO 전략입니다.": "IMO 2023 GHG Strategy · The IMO strategy setting net zero for international shipping by or around 2050, with indicative checkpoints for 2030 and 2040.",
"IMO Net-Zero Framework 승인과 채택 연기 · 연료 표준과 온실가스 가격제를 묶은 IMO 중기조치가 2025년 4월 승인됐지만, 10월 채택 회의가 1년 연기됐습니다.": "IMO Net-Zero Framework: approval and adoption delay · The IMO mid-term measure, combining a fuel standard and GHG pricing, was approved in April 2025, but the October adoption session was postponed by a year.",
"NZF 2026년 재논의 · 2026년 4월 MEPC 84에서도 채택되지 않았지만 유일한 최종안으로 남았고, 2026년 11월 30일~12월 3일 MEPC 85에서 채택을 다시 시도합니다.": "NZF: renewed discussion in 2026 · Not adopted at MEPC 84 in April 2026 either, but it remains the only final text; adoption will be attempted again at MEPC 85, 30 November~3 December 2026.",
"친환경선박법 · 친환경선박 개발·보급 지원의 근거법입니다. LNG 등 화석연료 추진선도 친환경선박 범위에 들어갑니다.": "Eco-friendly Ship Act · The legal basis for supporting eco-friendly ship development and deployment. Ships powered by fossil fuels such as LNG fall within the scope of eco-friendly ships.",
"녹색해운항로 구축 지원 특별법 · 저탄소·무탄소 연료 선박과 연료공급 항만을 잇는 “녹색해운항로”를 지정·지원하는 법입니다. 녹색선박 범위에 LNG가 없습니다.": "Green Shipping Corridor Act · The law designating and supporting “green shipping corridors” linking low and zero-carbon fuelled ships with fuel-supplying ports. LNG is not within the scope of green ships.",
"제1차 친환경선박 개발·보급 기본계획 (2021~2030) · 2030년까지 528척을 친환경선박으로 바꾸는 첫 10년 계획입니다. 2021~2025년 이행 기록은 확인되고, 2030년 목표의 달성 실적은 공개되지 않았습니다.": "1st Basic Plan for Eco-friendly Ship Development and Deployment (2021~2030) · The first ten-year plan, converting 528 ships to eco-friendly ships by 2030. Implementation records for 2021~2025 are confirmed; results against the 2030 target have not been disclosed.",
"국제해운 탈탄소화 추진전략 (2023.2) · 5,000톤 이상 국적 외항선 867척을 2050년까지 친환경선으로 바꾸는 범부처 전략입니다. 발표 직후 메탄올선 발주와 금융 지원이 이어졌습니다.": "International Shipping Decarbonisation Strategy (2023.2) · A cross-ministry strategy to convert 867 Korean-flagged ocean-going ships of 5,000 t or more to eco-friendly ships by 2050. Methanol ship orders and financial support followed shortly after announcement.",
"K-조선 차세대 선도전략 (2023.11) · 조선업 초격차를 위해 2028년까지 7,100억을 투입하는 산업부 전략입니다.": "K-Shipbuilding Next-Generation Leadership Strategy (2023.11) · A MOTIE strategy investing KRW 710bn by 2028 to secure a decisive lead in shipbuilding.",
"제2차 친환경선박 개발·보급 기본계획 (2026~2035) · 2035년까지 889척 전환, 외항선대 배출 61% 감축, 무탄소선 시장 점유율 50%를 목표로 한 두 번째 10년 계획입니다.": "2nd Basic Plan for Eco-friendly Ship Development and Deployment (2026~2035) · The second ten-year plan, targeting 889 ships converted by 2035, a 61% cut in ocean-going fleet emissions and a 50% share of the zero-carbon ship market.",
"2022 친환경선박 개발시행계획 956억 · 산업부가 수립한 개발시행계획의 2022년 예산입니다.": "2022 eco-friendly ship development implementation plan KRW 95.6bn · The 2022 budget of the development implementation plan drawn up by MOTIE.",
"2023 친환경선박 개발시행계획 1,454억 · 전년보다 약 52% 늘었고, 증액분은 수소·암모니아·전기 등 무탄소 기술에 집중됐습니다.": "2023 eco-friendly ship development implementation plan KRW 145.4bn · Up about 52% on the previous year, with the increase concentrated on zero-carbon technologies such as hydrogen, ammonia and electric.",
"2024 개발시행계획 총액 · 2024년 개발시행계획 총액을 밝힌 정부 보도자료·언론 보도를 찾지 못했습니다.": "2024 development implementation plan total · No government press release or media report stating the 2024 development implementation plan total was found.",
