"2026 산업부 조선 R&D 3,200억 · 역대 최대 조선 R&D 예산입니다. AI·자율운항 등이 함께 들어 있어 2022·2023 친환경선박 개발시행계획과 직접 비교할 수 없습니다.": "2026 MOTIE shipbuilding R&D KRW 320bn · The largest shipbuilding R&D budget to date. As it also covers AI and autonomous shipping, it cannot be compared directly with the 2022 · 2023 eco-friendly ship development implementation plans.",
"2027 산업부 예산안 (국회 심의 중) · 무탄소·AI 자율운항 선박 R&D 2,134억이 신설 편성됐습니다.": "2027 MOTIE budget proposal (under National Assembly review) · A new KRW 213.4bn allocation for zero-carbon and AI autonomous ship R&D.",
