"2026 해수부 친환경선박 보급 445억 (정부안) · IMO 규제 대응 “친환경선박 보급” 예산이 335억에서 445억으로 늘었습니다. 관공선 건조가 포함된 보급 시행계획 총액과는 범위가 다릅니다.": "2026 MOF eco-friendly ship deployment KRW 44.5bn (government proposal) · The “eco-friendly ship deployment” budget for responding to IMO regulation rose from KRW 33.5bn to KRW 44.5bn. Its scope differs from the deployment implementation plan total, which includes government vessel construction.",
