"01 규제": "01 Regulation",
"IMO 넷제로 프레임워크가 유예된 상황에서 여섯 시나리오로 한국 해운의 비용을 계산했습니다. 늦출수록 장기 비용이 커지고, 결정적 지렛대는 정부 정책입니다.": "With the IMO Net-Zero Framework postponed, we calculated the cost to Korean shipping under six scenarios. The longer the delay, the higher the long-term cost, and the decisive lever is government policy.",
"보고서 보기": "Read the report",
"배출 상한과 탄소 가격을 담은 IMO 중기조치가 선사의 연료 선택과 운송비를 어떻게 바꾸는지 세 시나리오로 추정했습니다.": "We estimated, under three scenarios, how IMO mid-term measures combining an emissions cap and a carbon price change shipping companies' fuel choices and freight costs.",
"IMO MEPC 83/7/22 기여": "IMO MEPC 83/7/22 contribution",
"2050 국제해운 넷제로를 위한 연료 전환 권고. 감축비용 모델에 근거해 e-연료 조기 사용에 대한 재정 지원, 기존 연료 가격에 탄소 비용 내재화, 더 높은 중간 목표를 제안했습니다.": "Recommendations on the fuel transition for net zero in international shipping by 2050. Based on an abatement cost model, we proposed financial support for early e-fuel uptake, internalising carbon costs in incumbent fuel prices, and higher interim targets.",
"IMO 넷제로 프레임워크 아래 미준수, 기본 목표, 강화 목표의 세 시나리오를 모델링했습니다. 중기조치가 실질적인 연료 전환을 이끌 수 있는지, 어디에 정책 개입이 필요한지 짚습니다.": "We modelled three scenarios under the IMO Net-Zero Framework: non-compliance, base target and strengthened target. We examine whether the mid-term measures can drive a real fuel transition and where policy intervention is needed.",
"02 전환": "02 Transition",
"탄소 락인(Carbon Lock-in), 국제해운 탈탄소는 지연 중": "Carbon lock-in: decarbonisation of international shipping is stalling",
"LNG 중심의 연료 전환이 해운의 탄소 락인을 부른다는 분석입니다. 총배출을 직접 규제해야 e-연료 중심의 감축이 가능합니다.": "An analysis showing that an LNG-led fuel transition locks shipping into carbon. Only direct regulation of total emissions enables abatement centred on e-fuels.",
"정책 지원 시 2026~2050년 84.7조 원의 추가 수주, 56.5조 원의 부가가치, 약 19.5만 명의 직접 고용. 수주잔량이 바닥나는 2029년 이전이 관건입니다.": "With policy support, KRW 84.7tn in additional orders, KRW 56.5tn in value added and about 195,000 direct jobs over 2026–2050. The key is acting before order backlogs run dry in 2029.",
"녹색항로의 실현 조건 (Green Shipping Council)": "Conditions for green corridors (Green Shipping Council)",
"녹색항로를 선언에서 운항으로. 첫 무탄소 상업 운항에 필요한 계약, 연료, 항만, 재원의 조건을 3년간 계량합니다.": "Taking green corridors from declaration to operation. Over three years we quantify the contract, fuel, port and finance conditions needed for the first zero-emission commercial voyage.",
"생태계 지도 · 한 장 캔버스 펼치기": "Open ecosystem map · one-page canvas",
"04 거버넌스": "04 Governance",
"Shadow Fleet과 해양보호구역": "Shadow fleets and marine protected areas",
"규제 밖 그림자 선단이 보호구역을 드나들 때, 모니터링 인프라를 감시에 쓰는 구상입니다.": "A concept for using monitoring infrastructure for surveillance when unregulated shadow fleets move through protected areas.",
"PLANiT · 신규": "PLANiT · New",
"메탄올·암모니아, 항만은 준비됐나": "Methanol and ammonia: are ports ready?",
"대체연료 벙커링의 경제성과 환경 영향. 병목은 배가 아니라 항만일 수 있습니다.": "The economics and environmental impact of alternative-fuel bunkering. The bottleneck may be the port, not the ship.",
"03 확산": "03 Scale up",
"설계 제안": "Design proposal",
"공적 보전, 선박금융, 화주 장기계약이 각각 언제 무엇을 지불할지 설계합니다.": "Designing when and what public gap funding, ship finance and cargo owners' long-term contracts each pay.",
"동아시아 공동 항로: 네트워크 효과의 계량": "East Asian joint corridors: quantifying network effects",
"대만·일본과 함께 여는 공동 항로. 항로가 늘어날 때의 물동량과 벙커링 수요를 추정합니다.": "Joint corridors opened with Taiwan and Japan. We estimate cargo volumes and bunkering demand as corridors multiply.",
