"시행령·시행규칙 입법예고(2026.9.2~10.13), 2027년 2월 확정 예정. 녹색선박 연료 범위(메탄올·수소·암모니아·바이오·재생합성연료, 전기·연료전지), 연료 공급체계를 갖춘 항만 요건, 기본계획, 지역별 지원협의체를 정합니다. 제2차 친환경선박 기본계획(2026–2035)과 함께 갑니다.": "Enforcement decree and rules pre-announced (2 Sep to 13 Oct 2026), due to be finalised in February 2027. They set the scope of green ship fuels (methanol, hydrogen, ammonia, bio and renewable synthetic fuels, electricity, fuel cells), requirements for ports with fuel supply systems, the basic plan and regional support councils. They go hand in hand with the 2nd Eco-friendly Ship Basic Plan (2026–2035).",
