"수요 확약이 없으면 발주가 없고, 발주가 없으면 연료 생산 투자도 없다. 서로 기다리는 교착": "No demand commitments means no orders, and no orders means no fuel production investment. A deadlock where everyone waits for everyone else",
"IMO 넷제로 프레임워크 채택 연기(2025.10). 탄소 규제 비용의 예측 가능성이 약화되면서 투자 경제성 평가의 핵심 전제가 흔들리고, 선박·연료·인프라 전반의 투자 의사결정 불확실성 확대": "IMO Net-Zero Framework adoption postponed (Oct 2025). Weaker predictability of carbon regulation costs undermines a core assumption of investment appraisals and widens uncertainty over investment decisions across ships, fuels and infrastructure",
"가격 격차를 메울 재원 구조가 아직 없음": "No funding structure yet to close the price gap",
