"2025년 4월 MEPC 83에서 초안이 승인됐지만 2025년 10월 채택이 연기됐습니다. 초안 수치로 비용을 미리 보려면 시나리오를 켜세요.": "The draft was approved at MEPC 83 in April 2025, but adoption was postponed in October 2025. Turn on the scenario to preview costs using the draft figures.",
