"이 계산기는 연구용 추정 도구입니다. 실제 규제 비용은 검증 방법론, 연료 인증, 풀링·뱅킹, 항차별 적용 범위 같은 세부 규칙에 따라 달라집니다. 규정 수치는 2026년 9월 기준입니다. 모델 원본(엑셀)과 가정 시트가 필요하시면": "This calculator is a research estimation tool. Actual regulatory costs depend on detailed rules such as verification methodology, fuel certification, pooling and banking, and voyage-level scope. Regulatory figures are as of September 2026. If you need the original model (Excel) and assumptions sheet, please",
