"ETS 비용 = 배출량 × 과금 비중 × 단계 적용률(2024 40%, 2025 70%, 2026년부터 100%) × EUA. 2026년 배출분부터 CH₄·N₂O 포함, GWP 28/265로 환산.": "ETS cost = emissions × coverage share × phase-in rate (40% in 2024, 70% in 2025, 100% from 2026) × EUA. CH₄ and N₂O included from 2026 emissions, converted at GWP 28/265.",
"GHG 원단위 = Σ(에너지 × WtW) ÷ Σ에너지. WtW = WtT + [(1−슬립)(Cf": "GHG intensity = Σ(energy × WtW) ÷ Σenergy. WtW = WtT + [(1−slip)(Cf",
"×298) + 슬립×25] ÷ LCV (FuelEU Annex I, 기본값 Annex II).": "×298) + slip×25] ÷ LCV (FuelEU Annex I, defaults from Annex II).",
"준수 잔액 = (목표 − 원단위) × 과금 에너지. 벌금 = |잔액| ÷ (원단위 × 41,000) × 2,400 EUR, 연속 n년째 × (1 + (n−1)/10). 목표는 91.16의 −2% (2025~), −6% (2030~), −14.5% (2035~).": "Compliance balance = (target − intensity) × covered energy. Penalty = |balance| ÷ (intensity × 41,000) × 2,400 EUR, × (1 + (n−1)/10) in the nth consecutive year. Target is 91.16 reduced by 2% (2025–), 6% (2030–), 14.5% (2035–).",
