"), 이중연료 파일럿 연료는 반영하지 않았습니다. 출력 제한 근사는 속도가 출력의 세제곱근에 비례한다고 본 값입니다.": "), and dual-fuel pilot fuel are not included. The power limitation approximation assumes speed is proportional to the cube root of power.",
