"← Tool 목록으로": "← Back to tools",
"기준 체계 (GWP·보상계수)": "Reference framework (GWP · reward factor)",
"어느 규제의 눈으로 볼지 선택합니다. 같은 연료라도 GWP 값에 따라 결과가 달라집니다.": "Choose which regulation's lens to apply. The same fuel can give different results depending on GWP values.",
"IMO LCA 지침 (AR5)": "IMO LCA Guidelines (AR5)",
"AR6 참고": "AR6 reference",
"사용자 정의": "Custom",
"RFNBO 보상계수 (FuelEU)": "RFNBO reward factor (FuelEU)",
"미적용": "Not applied",
"적용 (×2, 2033년까지)": "Applied (×2, until 2033)",
"RFNBO 연료(e-메탄올, e-암모니아)에서만 쓸 수 있습니다.": "Available only for RFNBO fuels (e-methanol, e-ammonia).",
"FuelEU는 RED II와 정합한 AR4 값(CH₄ 25, N₂O 298)을, IMO LCA 지침(MEPC.376(80), MEPC.391(81) 개정)은 AR5 값(CH₄ 28, N₂O 265)을 사용합니다. 메탄 슬립이 있는 LNG 계열에서 두 체계의 차이가 가장 큽니다. IMO 지침은 계속 개정 중이므로 사용자 정의 입력으로 최신 값을 반영하세요. \"IMO LCA 지침\"을 고르면 GWP와 함께 메탄 슬립(MEPC.391(81))과 LCV(MEPC.364(79)) 기본값도 IMO 값으로 바뀝니다.": "FuelEU uses AR4 values aligned with RED II (CH₄ 25, N₂O 298); the IMO LCA Guidelines (MEPC.376(80), amended by MEPC.391(81)) use AR5 values (CH₄ 28, N₂O 265). The gap between the two frameworks is largest for LNG pathways with methane slip. The IMO guidelines are still being revised, so use custom inputs to apply the latest values. Selecting \"IMO LCA Guidelines\" also switches the methane slip (MEPC.391(81)) and LCV (MEPC.364(79)) defaults to IMO values, along with GWP.",
"IMO 화석연료 WtT 기본값은 아직 확정되지 않아 FuelEU 값을 씁니다 (2026 MEPC 84 기준).": "IMO WtT defaults for fossil fuels are not yet finalised, so FuelEU values are used (as of MEPC 84, 2026).",
"연료 선택": "Fuel selection",
"FuelEU Annex II 기본값이 자동 입력됩니다. 대체연료 일부는 예시값이므로 인증값(RED II 실제값, FLC 등)으로 수정해 사용하세요.": "FuelEU Annex II defaults are filled in automatically. Some alternative fuel values are illustrative, so replace them with certified values (RED II actual values, FLC, etc.).",
