"Well-to-Tank (WtT) 단계별 조정": "Well-to-Tank (WtT) adjustment by stage",
"규정은 WtT 합계 하나만 제시하므로, 세 하위 단계 배분은 문헌 기반 예시 비율입니다. 각 값을 조정하면 합계가 계산에 반영됩니다. 단위: gCO₂eq/MJ": "The regulations give only a single WtT total, so the split across three sub-stages is an illustrative, literature-based allocation. Adjusted values feed into the total used in the calculation. Unit: gCO₂eq/MJ",
"1. 원료 채취·생산": "1. Feedstock extraction · production",
"2. 연료 전환·생산": "2. Fuel conversion · production",
"3. 운송·저장·벙커링": "3. Transport · storage · bunkering",
"WtT 합계": "WtT total",
"Tank-to-Wake (TtW) 조정": "Tank-to-Wake (TtW) adjustment",
"연소 배출계수(연료 1g당 배출 g)와 메탄 슬립을 조정합니다. 슬립은 연료 질량 중 미연소 CH₄로 빠져나가는 비율입니다.": "Adjust combustion emission factors (g emitted per g of fuel) and methane slip. Slip is the share of fuel mass that escapes as unburnt CH₄.",
"gCO₂/g연료": "gCO₂/g fuel",
"gCH₄/g연료": "gCH₄/g fuel",
"gN₂O/g연료": "gN₂O/g fuel",
"메탄 슬립": "Methane slip",
"% (연료 질량 기준)": "% (by fuel mass)",
"암모니아의 연소 N₂O와 미연소 NH₃ 슬립 계수는 아직 규제상 확정되지 않았습니다. 기본값 0은 \"미확정\"의 의미이므로, 엔진 실측 문헌값을 직접 입력해 민감도를 확인하세요. N₂O는 GWP가 커서 소량으로도 결과가 크게 움직입니다.": "Combustion N₂O and unburnt NH₃ slip factors for ammonia are not yet set in regulation. The default of 0 means \"not determined\", so enter measured engine values from the literature to test sensitivity. N₂O has a high GWP, so even small amounts move the result significantly.",
"Well-to-Wake 결과": "Well-to-Wake results",
