"계단선: FuelEU GHG 집약도 목표 (기준 91.16 gCO₂eq/MJ 대비 감축률 적용) · 점선: IMO NZF 초안 (2025.4 MEPC 83 승인, 2025.10 채택 연기 · 미채택)의 GFI 기준선 93.3과 ZNZ 문턱값 (2034년까지 19.0, 2035년부터 14.0 gCO₂eq/MJ) · 굵은 가로선: 현재 설정 연료": "Step line: FuelEU GHG intensity target (reductions applied to the 91.16 gCO₂eq/MJ reference) · Dashed lines: IMO NZF draft (approved at MEPC 83 in April 2025, adoption postponed in October 2025 · not adopted) GFI baseline 93.3 and ZNZ threshold (19.0 gCO₂eq/MJ until 2034, 14.0 from 2035) · Bold horizontal line: fuel as currently configured",
"FuelEU 컴플라이언스 밸런스·페널티 추정": "FuelEU compliance balance · penalty estimate",
"연간 연료 사용량을 넣으면 해당 연도 목표 대비 잉여·부족분(CB)과 페널티를 추정합니다. 단일 연료 가정의 근사치입니다.": "Enter annual fuel consumption to estimate the surplus or deficit (CB) against that year's target and the resulting penalty. Approximation assuming a single fuel.",
"연간 연료 사용량": "Annual fuel consumption",
"톤": "t",
"대상 연도": "Target year",
"에너지 사용량": "Energy used",
"자동 계산": "Calculated automatically",
"비고": "Notes",
"목표 집약도": "Target intensity",
"실적 집약도 (보상계수 반영)": "Attained intensity (with reward factor)",
"컴플라이언스 밸런스 (CB)": "Compliance balance (CB)",
"tCO₂eq (양수=잉여, 음수=부족)": "tCO₂eq (positive = surplus, negative = deficit)",
"페널티 추정": "Penalty estimate",
"EUR, |CB|/(집약도×41,000)×2,400": "EUR, |CB|/(intensity×41,000)×2,400",
"페널티는 한 해, 보고 범위 100% 기준의 추정치입니다. 연속 미준수 시 n번째 해에는 ×(1+(n−1)/10)가 붙습니다 (제23조 2항).": "The penalty is a single-year estimate assuming 100% reporting scope. For consecutive non-compliance, ×(1+(n−1)/10) applies in the nth year (Art. 23(2)).",
"CB가 양수면 풀링·뱅킹으로 활용 가능한 잉여입니다. 페널티 공식은 FuelEU Annex IV의 VLSFO 에너지 등가(41,000 MJ/t) 기준입니다. 실제 정산은 항차 범위(역내 100%·역외 50%), OPS 의무, 풀링 구성에 따라 달라집니다.": "A positive CB is surplus available for pooling and banking. The penalty formula uses the VLSFO energy equivalent in FuelEU Annex IV (41,000 MJ/t). Actual settlement depends on voyage scope (intra-EU 100% · extra-EU 50%), OPS obligations and pool composition.",
"근거": "Basis",
"방법론·출처": "Methodology · sources",
"계산식": "Formulas",
"] ÷ LCV, s = 슬립 비율": "] ÷ LCV, s = slip ratio",
"CB = (목표 집약도 − 실적 집약도) × 사용 에너지(MJ)": "CB = (target intensity − attained intensity) × energy used (MJ)",
"RFNBO 보상계수: 2033년까지 해당 에너지를 2배로 계상(FuelEU 제5조). 본 툴은 단일 연료 가정에서 실적 집약도를 2로 나누는 방식으로 근사합니다.": "RFNBO reward factor: the relevant energy is counted twice until 2033 (FuelEU Art. 5). Assuming a single fuel, this tool approximates it by dividing the attained intensity by 2.",
"데이터 출처와 한계": "Data sources and limitations",
"화석연료 LCV·WtT·배출계수: Regulation (EU) 2023/1805 (FuelEU Maritime) Annex II 기본값.": "Fossil fuel LCV, WtT and emission factors: Regulation (EU) 2023/1805 (FuelEU Maritime) Annex II defaults.",
"IMO 값 세트: LCV는 MEPC.364(79), LNG 메탄 슬립은 MEPC.391(81) 기본값(Otto 중속 3.5%, Otto 저속 1.7%, Diesel 저속 0.15%, LBSI 2.6%). IMO 화석연료 WtT 기본값은 아직 확정되지 않아 FuelEU 값을 씁니다 (2026 MEPC 84 기준).": "IMO value set: LCV from MEPC.364(79); LNG methane slip defaults from MEPC.391(81) (Otto medium-speed 3.5%, Otto slow-speed 1.7%, Diesel slow-speed 0.15%, LBSI 2.6%). IMO WtT defaults for fossil fuels are not yet finalised, so FuelEU values are used (as of MEPC 84, 2026).",
"GWP: AR4 (FuelEU·RED II 정합), AR5 (IMO LCA 지침 MEPC.376(80)·MEPC.391(81)), AR6 참고값.": "GWP: AR4 (aligned with FuelEU · RED II), AR5 (IMO LCA Guidelines MEPC.376(80) · MEPC.391(81)), AR6 reference values.",
"IMO 기준선: IMO NZF 초안 (2025.4 MEPC 83 승인, 2025.10 채택 연기 · 미채택). GFI 기준 93.3 gCO₂eq/MJ (2008), ZNZ 문턱값 2034년까지 19.0, 2035년부터 14.0 gCO₂eq/MJ. 확정된 규정이 아니므로 채택 문서로 재확인 필요.": "IMO baseline: IMO NZF draft (approved at MEPC 83 in April 2025, adoption postponed in October 2025 · not adopted). GFI reference 93.3 gCO₂eq/MJ (2008); ZNZ threshold 19.0 gCO₂eq/MJ until 2034 and 14.0 from 2035. Not a finalised regulation, so verify against the adopted text.",
"바이오·e-연료의 WtT는 예시값입니다. 실제 컴플라이언스에는 RED II 인증 실제값 또는 IMO FLC(연료 라이프사이클 라벨) 값을 사용해야 합니다.": "WtT values for bio- and e-fuels are illustrative. Actual compliance requires RED II certified actual values or IMO FLC (Fuel Lifecycle Label) values.",
"WtT의 3단계 분해 비율은 설명용 예시 배분이며, 규정 기본값은 합계만 제공합니다.": "The three-stage WtT split is an illustrative allocation; regulatory defaults give only the total.",
"선박연료 LCA · 연구·교육용 도구이며, 규제 정산의 법적 근거가 아닙니다.": "Marine fuel LCA · a research and teaching tool, not a legal basis for regulatory settlement.",
"튜토리얼 1 / 9": "Tutorial 1 / 9",
"이 툴이 하는 일": "What this tool does",
"선박연료 1MJ당 온실가스(gCO₂eq/MJ)를 Well-to-Tank(생산·공급)와 Tank-to-Wake(선상 연소)로 나눠 계산하고, 합계인 Well-to-Wake를 FuelEU 목표 경로와 IMO 기준선에 대조합니다. 모든 단계의 값을 직접 조정할 수 있어 민감도 분석에 쓸 수 있습니다.": "It calculates greenhouse gas emissions per MJ of marine fuel (gCO₂eq/MJ), split into Well-to-Tank (production · supply) and Tank-to-Wake (onboard combustion), and compares the Well-to-Wake total with the FuelEU target pathway and the IMO baseline. Every stage can be adjusted directly, so it can be used for sensitivity analysis.",
