"연도별 CII 등급 전망": "CII rating outlook by year",
"그래프의 색상 영역은 연도별 CII 등급(A~E) 판정 기준을, 수평선은 해당 선박의 CII 값을 나타냅니다. 2031년 이후는 IMO의 CII 감축률 미설정으로 분석에서 제외하였습니다.": "The coloured bands show the CII rating thresholds (A–E) for each year, and the horizontal line shows this ship's CII. Years after 2031 are excluded because IMO has not yet set CII reduction factors for them.",
"C등급 유지를 위한 연간 CO₂ 배출 허용량": "Annual CO₂ allowance to keep a C rating",
"동일한 운항거리를 기준으로 CII C등급 유지에 필요한 연도별 최대 CO₂ 배출량을 나타냅니다. 막대는 연도별 배출 허용량을, 점선은 해당 선박의 현재 연간 CO₂ 배출량을 나타냅니다.": "Maximum annual CO₂ emissions needed to keep a CII C rating for the same distance sailed. Bars show each year's allowance; the dotted line shows this ship's current annual CO₂ emissions.",
