"항해·정박 구분 보고(2027년~):": "Separate at-sea and in-port reporting (from 2027):",
"2027년 보고분부터 선박이 항해 중일 때와 정박 중일 때의 배출량 및 운항거리를 각각 구분하여 보고해야 합니다. 단, CII는 기존과 같이 연간 전체 배출량과 운항거리를 합산하여 산정합니다(": "From the 2027 reporting year, ships must report emissions and distance separately for time at sea and time in port. CII is still calculated from total annual emissions and distance, as before (",
