"메탄올 · 파일럿 SFC 기본값은 2행정 메탄올 이중연료 엔진 예시입니다. NOx 기술파일 값을 넣으세요. 메탄올은 발열량이 낮아 SFC가 디젤의 약 2배입니다.": "The default methanol and pilot SFC values are for an example two-stroke methanol dual-fuel engine. Enter the NOx Technical File values. Methanol has a low calorific value, so its SFC is about twice that of diesel.",
