"주기관 출력 제한(EPL) 수준에 따른 EEXI 변화를 나타냅니다. EEXI가 요구기준 이하로 낮아지는 지점을 기준으로 규제 충족에 필요한 출력 제한 수준을 산정합니다.": "Shows how EEXI changes with the level of engine power limitation (EPL). The limitation needed for compliance is set at the point where EEXI falls below the requirement.",
