". 이 배는 a": ". For this ship, a",
"· EEDI 기준선 대비 낮춰야 하는 비율로, 선종·크기에 따라 0~50%. 한 번 정해지면 바뀌지 않음. 이 배는": "· Required reduction below the EEDI reference line, 0–50% depending on ship type and size. Fixed once set. For this ship:",
"이중연료 주연료 판정(2026년~):": "Primary fuel determination for dual fuel (from 2026):",
"이중연료 엔진은 연료별 CO₂ 환산계수에 그 연료의 연료소모율을 곱해 계산합니다. LNG는 설계 조건에서 전체 연료 발열량의 50% 이상이면 주연료로 보며, 최종 판단은 기국이 합니다. 메탄올·에탄올처럼 두 액체 연료를 쓰는 엔진의 주연료 판정도 함께 정리됐습니다(": "Dual-fuel engines are calculated by multiplying each fuel's CO₂ conversion factor by that fuel's specific fuel consumption. LNG is treated as the primary fuel if it provides 50% or more of total fuel energy under design conditions; the final decision rests with the flag State. Primary fuel determination for engines using two liquid fuels, such as methanol or ethanol, has also been set out (",
"출력 · 연료소모율 기준(2026년~):": "Power and specific fuel consumption basis (from 2026):",
"주기관 출력과 연료소모율은 모두 NOx 기술코드 2008로 인증된 MCR을 기준으로 정합니다(": "Main engine power and specific fuel consumption are both based on the MCR certified under the NOx Technical Code 2008 (",
"이 계산기가 하는 일": "What this calculator does",
"선박 정보를 한 번 넣고, CII(해마다 매기는 운항 등급)와 EEXI(배의 설계 효율)를 각각 따로 계산합니다. 둘 중 필요한 것만 골라 보면 됩니다.": "Enter the ship details once, and CII (the annual operational rating) and EEXI (the ship's design efficiency) are calculated separately. Look at whichever you need.",
"1. 대상 선박": "1. Target ship",
"선종, 재화중량, 총톤수는 CII와 EEXI에 함께 쓰입니다. 넣으면 두 계산의 기준선과 감축률이 자동으로 정해집니다.": "Ship type, deadweight and gross tonnage are used for both CII and EEXI. Entering them sets the reference lines and reduction factors for both calculations automatically.",
"2. CII 입력": "2. CII inputs",
"1년 동안 쓴 연료와 항해 거리를 넣습니다. 이중연료선은 가스, 파일럿 연료, 발전기 연료를 모두 넣으세요. 입력을 바꾸면 계산 버튼 색이 바뀌고, 누르면 결과가 새로 나옵니다.": "Enter the fuel used and distance sailed over one year. For dual-fuel ships, enter gas, pilot and generator fuel. When you change an input the calculate button changes colour; press it to refresh the results.",
"3. CII 결과": "3. CII results",
"등급과 A~E 띠 위 이 배의 위치, 연도별 등급 전망을 보여줍니다. 아래 계산 근거에서 IMO 원문으로 바로 이동할 수 있습니다.": "Shows the rating, this ship's position on the A–E band and the rating outlook by year. From the calculation basis below you can go straight to the IMO source text.",
"4. EEXI는 따로": "4. EEXI separately",
"위의 EEXI 버튼을 누르면 설계값 입력으로 바뀝니다. 이중연료 엔진은 가스·파일럿 SFC를 넣고, 출력 제한(EPL)을 켜서 제한 전후를 비교할 수 있습니다.": "Press the EEXI button above to switch to design-value inputs. For dual-fuel engines, enter the gas and pilot SFC, and turn on engine power limitation (EPL) to compare before and after the limit.",
"1-OCEAN · 탄소 비용 계산기": "1-OCEAN · Carbon Cost Calculator",
