"대기에 얼마나 머무는가": "How long it stays in the air",
"메탄은 강하지만 짧게, CO₂는 약하지만 수백 년 이상 남습니다. 20년 기준(GWP20)과 100년 기준(GWP100)의 숫자가 크게 다른 이유입니다. 배출 1단위가 시간이 지나며 대기에 남는 비율입니다.": "Methane is strong but short-lived; CO₂ is weaker but lingers for centuries or longer. That is why the 20-year (GWP20) and 100-year (GWP100) numbers differ so much. The curves show the share of one unit of emissions remaining in the atmosphere over time.",
"CH₄ · 평균 체류 약 12년": "CH₄ · mean lifetime about 12 years",
"N₂O · 약 109년": "N₂O · about 109 years",
"CO₂ · 단일 수명 없음, 일부는 수천 년": "CO₂ · no single lifetime, some lasts millennia",
"어디서 배출되는가": "Where it is emitted",
"CO₂와 메탄은 지구 전체에 고르게 섞이지만, 함께 나오는 블랙카본과 황·질소산화물은 배출된 곳에서 영향이 갈립니다.": "CO₂ and methane mix evenly around the globe, but the black carbon and sulphur and nitrogen oxides emitted alongside them have effects that depend on where they are released.",
"북극": "Arctic",
"블랙카본이 얼음을 녹인다": "Black carbon melts the ice",
"눈과 얼음 위에 내려앉은 블랙카본은 햇빛 반사율을 낮춰 해빙을 앞당깁니다. 북극 해운의 블랙카본 배출은": "Black carbon settling on snow and ice lowers its reflectivity and speeds up melting. Black carbon emissions from Arctic shipping",
"2015~2021년 두 배": "doubled between 2015 and 2021",
"로 늘었습니다.": ".",
"IMO의 북극 중유 금지는": "IMO's Arctic heavy fuel oil ban took effect in",
"2024년 7월": "July 2024",
"시행됐지만 예외 조항이 2029년까지 남아, 그 사이에는 중유 운반선의 약": ", but exemptions remain until 2029, so in the meantime it applies to only about",
"에만 적용됩니다.": "of heavy fuel oil carriers.",
"연안 · 항만": "Coast · Ports",
"황과 미세먼지는 사람에게 닿는다": "Sulphur and particulates reach people",
"2020년 저황 연료 이전, 선박 대기오염은 해마다 조기 사망 약": "Before low-sulphur fuel in 2020, ship air pollution was estimated to be linked each year to about",
"40만 명": "400,000 premature deaths",
", 소아 천식 약": "and about",
"1,400만 건": "14 million cases of childhood asthma",
"과 관련된 것으로 추정됐습니다. 저황 연료는 조기 사망을 약 3분의 1, 소아 천식을 약 절반 줄일 것으로 봤습니다.": ". Low-sulphur fuel was expected to cut premature deaths by about a third and childhood asthma by about half.",
"배출규제해역(ECA)에서는 연료 황 함량을": "Emission Control Areas (ECAs) cap fuel sulphur content at",
"로 묶습니다.": ".",
"원양": "Open ocean",
"깨끗해진 배기가 냉각도 줄였다": "Cleaner exhaust also reduced cooling",
"2020년 IMO 황 상한(3.5% → 0.5%)으로 선박의 이산화황 배출이 약": "The 2020 IMO sulphur cap (3.5% → 0.5%) cut ships' sulphur dioxide emissions by about",
"줄었습니다. 구름을 밝게 하던 황 에어로졸이 줄면서, 바다 위 냉각 효과도 함께 줄었습니다.": ". As the sulphate aerosols that brightened clouds declined, their cooling effect over the ocean declined too.",
"한 연구는 그 효과가 2020년 이후 지구에 추가로 쌓인 열의 상당 부분에 해당한다고 추정했고, 다른 연구는 관측된 구름 변화의 일부만 설명한다고 봅니다.": "One study estimates the effect accounts for a large share of the extra heat the Earth has accumulated since 2020; another finds it explains only part of the observed change in clouds.",
"근거 · 2026년 10월 확인": "Sources · checked October 2026",
