"NZF 초안의 GFI 기준 93.3 gCO₂e/MJ(2008년). ZNZ 문턱값은 2034년까지 19.0, 2035년부터 14.0": "Draft NZF GFI baseline 93.3 gCO₂e/MJ (2008). ZNZ threshold 19.0 until 2034, 14.0 from 2035",
