"0 (잉여)": "0 (surplus)",
"1. 기준 체계부터 고른다": "1. Choose the framework first",
"FuelEU는 AR4 GWP(CH₄ 25), IMO LCA 지침은 AR5(CH₄ 28)를 씁니다. IMO 지침은 개정이 진행 중이므로, 새 값이 나오면 사용자 정의로 입력하세요. RFNBO 보상계수는 e-연료 선택 시 자동으로 켜집니다.": "FuelEU uses AR4 GWP (CH₄ 25); the IMO LCA Guidelines use AR5 (CH₄ 28). The IMO Guidelines are being revised, so enter new values as custom when they appear. The RFNBO reward factor switches on automatically when you choose an e-fuel.",
"2. 연료를 선택한다": "2. Choose the fuel",
"화석연료 5종은 FuelEU Annex II 규정 기본값이 그대로 들어갑니다. 바이오·e-연료는 예시값이므로 배지가 노란색으로 표시되며, RED II 인증값이나 IMO FLC 값으로 바꿔 쓰는 것이 원칙입니다. LNG는 엔진 유형별 슬립 기본값을 제공합니다.": "The five fossil fuels use the FuelEU Annex II default values as they are. Bio and e-fuels use illustrative values, shown with a yellow badge; in principle replace them with certified RED II or IMO FLC values. LNG comes with slip defaults by engine type.",
"3. WtT를 단계별로 조정한다": "3. Adjust WtT stage by stage",
"규정은 WtT 합계만 주지만, 이 툴은 원료·생산·운송의 3단계로 분해해 보여줍니다. 분해 비율은 예시이므로 절대값보다 '어느 단계를 바꾸면 합계가 얼마나 움직이는가'를 보는 용도입니다. 예: e-연료는 전력(원료) 단계가 지배적입니다.": "The rules give only a WtT total, but this tool splits it into feedstock, production and transport. The split is illustrative, so use it to see how much the total moves when one stage changes rather than for absolute values. For example, e-fuels are dominated by the electricity (feedstock) stage.",
"4. TtW와 슬립을 조정한다": "4. Adjust TtW and slip",
"메탄 슬립 1%p 변화가 LNG의 WtW를 얼마나 움직이는지 슬라이더로 확인해 보세요. 기준 체계를 IMO로 바꾸면 GWP(AR5)와 슬립·LCV 기본값이 함께 바뀝니다. 암모니아는 N₂O 계수가 미확정이라 직접 입력 항목입니다.": "Use the slider to see how far a 1 pp change in methane slip moves LNG's WtW. Switching the framework to IMO changes GWP (AR5) and the slip and LCV defaults together. Ammonia's N₂O factor is not finalised, so it is a manual input.",
"5. 결과 읽는 법": "5. Reading the results",
"스택 바는 WtW를 4개 단계로 분해한 것입니다. 화석연료는 TtW(남색)가, e-연료는 WtT가 지배적임을 한눈에 볼 수 있습니다. 아래 판정문은 FuelEU 목표를 몇 년도까지 충족하는지 알려줍니다.": "The stacked bar splits WtW into four stages. You can see at a glance that TtW (navy) dominates for fossil fuels and WtT for e-fuels. The verdict below tells you up to which year the fuel meets FuelEU targets.",
"6. 목표 경로와 대조한다": "6. Compare with the target pathway",
"금색 계단선이 FuelEU 목표(2025년 −2%에서 2050년 −80%까지), 남색 가로선이 현재 설정 연료입니다. 회색 점선은 IMO NZF 초안(미채택)의 GFI 기준선(93.3), 청록 점선은 ZNZ 문턱값(2034년까지 19.0, 2035년부터 14.0)입니다. 하단 점이 연도별 충족 여부입니다.": "The gold step line is the FuelEU target (−2% in 2025 to −80% in 2050); the navy horizontal line is the fuel currently set. The grey dotted line is the GFI baseline (93.3) of the draft IMO NZF (not adopted); the teal dotted line is the ZNZ threshold (19.0 until 2034, 14.0 from 2035). The dots at the bottom show compliance by year.",
"7. 컴플라이언스 밸런스": "7. Compliance balance",
"연간 연료량을 넣으면 목표 연도 기준 CB(tCO₂eq)와 페널티를 추정합니다. 양수면 풀링·뱅킹 가능한 잉여, 음수면 부족분입니다. 단일 연료·전체 에너지 적용 가정의 근사치라는 점만 유의하세요.": "Enter annual fuel volume to estimate the CB (tCO₂eq) and penalty for the target year. Positive means surplus available for pooling and banking; negative means a deficit. Note it is an approximation assuming a single fuel applied to all energy.",
"활용 팁": "Tips",
"같은 연료를 두고 GWP 체계만 바꿔 결과 차이를 기록하면, FuelEU와 IMO 지침의 정합성 이슈를 수치로 보여주는 자료가 됩니다. 값은 모두 초기화 버튼으로 되돌릴 수 있습니다. 이제 직접 사용해 보세요.": "Record the difference in results when you change only the GWP framework for the same fuel, and you have numbers showing the consistency gap between FuelEU and the IMO Guidelines. Every value can be reset with the reset button. Now try it yourself.",
"튜토리얼": "Tutorial",
"시작하기": "Get started",
