"손자병법의 프레임으로 네 개의 전장(비용·계약·발주·공급망)에 같은 세 질문을 던지고, 감내할 곳과 승부를 걸 곳을 가려냅니다.": "Using the frame of Sun Tzu's Art of War, it asks the same three questions of four battlefields (cost, contracts, orders, supply chains) to separate where to endure from where to compete.",
