"교체 주기는 위기인가 기회인가": "Is the replacement cycle a crisis or an opportunity?",
"한국 선대의 평균 선령이 말해주는 것, 그리고 벙커링 인프라가 비어 있는 항만의 지도.": "What the average age of the Korean fleet tells us, and a map of ports with no bunkering infrastructure.",
"경쟁국은 조선·해운·화주·금융을 하나의 구조로 묶어 발주의 위험을 나누고 있습니다. 격차를 데이터로 확인합니다.": "Competitors bind shipbuilding, shipping, cargo owners and finance into one structure to share ordering risk. We check the gap with data.",
"지연은 시간을 버는가, 비용을 쌓는가": "Does delay buy time, or pile up cost?",
"IMO NZF와 EU 규제의 시간표. 지연은 준비할 시간이 아니라 준비하지 않은 비용이 쌓이는 시간입니다.": "The timelines of IMO NZF and EU regulation. Delay is not time to prepare; it is time in which the cost of not preparing piles up.",
