/* ═══ 문장 단위 번역 (data-i 가 없는 곳 · 스크립트가 그리는 표·지도·패널 포함) ═══
   EN_TEXT 사전: 한국어 문장(공백 정리) → 영어. 영어 모드에서 화면의 글자 조각을 찾아 바꾸고,
   한국어로 돌아오면 원문을 되돌립니다. 화면이 새로 그려져도 자동으로 다시 번역합니다.
   이슈 브리프 문서(article#brief)와 인쇄 표지는 한국어 원문 그대로 둡니다.
   숫자·등급이 들어가는 문장은 키에 #(숫자)·@(A~E 등급) 자리표시를 씁니다.                  */
(function(){
  if(typeof EN_TEXT==='undefined') return;
  var NORM=function(t){return t.replace(/\s+/g,' ').trim()};
  var PAT=[[/^(\d+)건$/,'$1 results'],[/^(\d+) PROJECTS$/,'$1 PROJECTS']];
  /* 숫자·등급이 바뀌는 문장: 사전 키에 # (숫자) · @ (A~E 등급)을 쓰면 값만 바꿔 끼운다 */
  var NUM=/\d[\d,]*(?:\.\d+)?/g, GRD=/(^|[^A-Za-z])([A-E])(?=[\uac00-\ud7a3\s·)]|$)/g;
  function fill(en,nums,grs){return en.replace(/[#@]/g,function(c){return c==='#'?(nums.length?nums.shift():c):(grs.length?grs.shift():c)})}
  function tr(t){var k=NORM(t);if(!k)return null;if(EN_TEXT.hasOwnProperty(k))return EN_TEXT[k];
    for(var i=0;i<PAT.length;i++){if(PAT[i][0].test(k))return k.replace(PAT[i][0],PAT[i][1])}
    if(!/[\uac00-\ud7a3]/.test(k))return null;
    var nums=[],k2=k.replace(NUM,function(x){nums.push(x);return '#'});
    if(nums.length&&EN_TEXT.hasOwnProperty(k2))return fill(EN_TEXT[k2],nums.slice(),[]);
    var grs=[],k3=k2.replace(GRD,function(m,a,g){grs.push(g);return a+'@'});
    if(grs.length&&EN_TEXT.hasOwnProperty(k3))return fill(EN_TEXT[k3],nums.slice(),grs);
    return null}
  var SKIP='script,style,noscript,textarea,article#brief,#print-cover,.cmt-list,.fns';
  var ATTR=['placeholder','title','aria-label','alt','data-l'];
  var busy=false;
  function walk(root,toEn){
    if(!root||root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==3)return;
    if(root.nodeType===3){one(root,toEn);return}
    if(root.closest&&root.closest(SKIP))return;
    var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:function(n){var p=n.parentElement;return (p&&!p.closest(SKIP))?1:2}});
    var n,list=[];while(n=w.nextNode())list.push(n);list.forEach(function(x){one(x,toEn)});
    var els=root.querySelectorAll?[].slice.call(root.querySelectorAll('[placeholder],[title],[aria-label],[alt],[data-l]')):[];
    if(root.matches&&root.matches('[placeholder],[title],[aria-label],[alt],[data-l]'))els.push(root);
    [].forEach.call(els,function(el){if(el.closest(SKIP.replace('textarea,','')))return;ATTR.forEach(function(a){
      var v=el.getAttribute(a);if(v==null)return;var store='__ko_'+a;
      if(toEn){var e=tr(el[store]!=null&&v===el['__en_'+a]?el[store]:v);if(e!=null&&v!==e){el[store]=v;el['__en_'+a]=e;el.setAttribute(a,e)}}
      else if(el[store]!=null&&v===el['__en_'+a]){el.setAttribute(a,el[store]);el[store]=null}})});
  }
  function one(n,toEn){var v=n.nodeValue;
    if(toEn){if(n.__en!=null&&v===n.__en)return;var e=tr(v);if(e==null)return;
      var lead=v.match(/^\s*/)[0],trail=v.match(/\s*$/)[0];n.__ko=v;n.__en=lead+e+trail;n.nodeValue=n.__en}
    else if(n.__ko!=null&&v===n.__en){n.nodeValue=n.__ko;n.__ko=null;n.__en=null}}
  /* 좁은 칸의 SVG 글자는 넘치면 칸 폭에 맞춰 줄인다 (text.fit · data-max) */
  function fit(){[].forEach.call(document.querySelectorAll('svg text.fit'),function(t){t.removeAttribute('textLength');t.removeAttribute('lengthAdjust');
    var m=+t.getAttribute('data-max')||104;try{if(t.getComputedTextLength()>m){t.setAttribute('textLength',m);t.setAttribute('lengthAdjust','spacingAndGlyphs')}}catch(e){}})}
  function run(){busy=true;walk(document.body,LANG==='en');fit();busy=false}
  window.addEventListener('langchange',run);
  if(LANG==='en')run();
  var q=[],sched=false;
  new MutationObserver(function(ms){if(busy||LANG!=='en')return;ms.forEach(function(m){
      if(m.type==='characterData'||m.type==='attributes')q.push(m.target);else m.addedNodes.forEach(function(x){q.push(x)})});
    if(!sched){sched=true;requestAnimationFrame(function(){sched=false;busy=true;var a=q;q=[];a.forEach(function(x){if(x.isConnected)walk(x,true)});fit();busy=false})}})
    .observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:ATTR});
})();
